package net.flashlight.battery;
import fixture.Checks;import net.minecraft.world.item.ItemStack;import net.minecraft.client.Minecraft;
public class InventoryChecks9{static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static class Inv extends Checks.Inv{public void setItem(int i,ItemStack s){stacks[i]=s;}}public static class Actor extends ShadowChecks6.Actor{Inv inventory=new Inv();public Inv getInventory(){return inventory;}public boolean isAlive(){return true;}public boolean isSpectator(){return false;}}
 public static void main(String[]a){for(String type:Power.TYPES){var p=new Actor();var lamp=(ItemStack)Power.stack("flashlight:"+type+"_off");p.inventory.stacks[12]=lamp;Power.charge(lamp,100);Power.toggle(p);lamp=p.inventory.stacks[12];ok(Power.on(lamp)&&Power.active(p)==lamp,"X toggles saved lamp without holding it");Power.tick(p);ok(Power.remaining(lamp)==99,"inventory light consumes battery");var mc=Minecraft.INSTANCE;var world=new ShadowChecks6.World();p.world=world;mc.player=p;mc.level=world;Light6.tick();ok(Light6.cache.containsKey(p),"inventory light participates in actual client lighting tick");ok(Light6.cache.get(p).range==Power.RANGE[Power.tier(lamp)],"range follows stored model");Power.toggle(p);Light6.tick();ok(!Light6.cache.containsKey(p),"X off removes inventory source");Power.charge(p.inventory.stacks[12],1);Power.toggle(p);Power.tick(p);ok(!Power.on(p.inventory.stacks[12])&&Power.remaining(p.inventory.stacks[12])==0,"empty inventory battery turns light off");}
 var p=new Actor();var lamp=(ItemStack)Power.stack("flashlight:flashlight");Power.charge(lamp,100);p.main=lamp;p.inventory.stacks[0]=lamp;Power.tick(p);ok(Power.remaining(lamp)==99,"held stack shared with inventory drains only once");p.main=(ItemStack)Power.stack("minecraft:air");p.inventory.stacks[12]=lamp;p.inventory.stacks[0]=(ItemStack)Power.stack("minecraft:air");p.world.isClientSide=true;Power.tick(p);ok(Power.remaining(lamp)==99,"client cannot consume authoritative battery");System.out.println("ALL_TIER_X_INVENTORY_RENDER_DRAIN_EXPIRY_NO_DOUBLE_CONSUMPTION_CHECKS="+n);}
}
